INSERT INTO `pages` (`id`, `slug`, `title`, `body`, `status`, `publish_at`, `author_id`, `approved_by`, `created_at`, `updated_at`) VALUES (1,'sobre-idead','Sobre el IDEAD','<p>Contenido institucional pendiente de suministro por la Dirección del IDEAD (misión, visión, historia y estructura).</p>','publicado','2026-11-09 16:57:49',NULL,NULL,'2026-11-09 16:57:49','2026-11-09 16:57:49');
INSERT INTO `pages` (`id`, `slug`, `title`, `body`, `status`, `publish_at`, `author_id`, `approved_by`, `created_at`, `updated_at`) VALUES (2,'privacidad','Política de privacidad y tratamiento de datos personales','<p>El portal publica únicamente información agregada y autorizada. La política de tratamiento de datos personales de la Universidad del Tolima (Ley 1581 de 2012 y Decreto 1074 de 2015) debe enlazarse aquí: <strong>pendiente de suministro institucional</strong>.</p>','publicado','2026-11-09 16:57:49',NULL,NULL,'2026-11-09 16:57:49','2026-11-09 16:57:49');
INSERT INTO `pages` (`id`, `slug`, `title`, `body`, `status`, `publish_at`, `author_id`, `approved_by`, `created_at`, `updated_at`) VALUES (3,'accesibilidad','Accesibilidad','<p>Este portal se diseñó siguiendo las pautas WCAG 2.1 nivel AA: navegación por teclado, contraste suficiente, textos alternativos y tablas equivalentes para cada gráfico. Si encuentra una barrera de accesibilidad, comuníquese con el IDEAD.</p>','publicado','2026-11-09 16:57:49',NULL,NULL,'2026-11-09 16:57:49','2026-11-09 16:57:49');
